import psycopg, os, jinja2; from dotenv import load_dotenv; load_dotenv(); conn = psycopg.connect(dbname=os.environ.get('DB_NAME'), user=os.environ.get('DB_USER'), password=os.environ.get('DB_PASSWORD'), row_factory=psycopg.rows.dict_row); cur = conn.cursor(); cur.execute("SELECT k.id, k.room_number, k.monthly_rate, l.nama_lokasi FROM kamar k JOIN lokasi_kos l ON k.location_id = l.id WHERE k.status = 'AVAILABLE' ORDER BY l.id ASC, k.room_number ASC"); data = cur.fetchall(); print(data[0]); t = jinja2.Template("{% for kmr in kamar_tersedia %}{{ kmr.nama_lokasi }} {{ kmr.room_number }} Rp {{ '{:,.0f}'.format(kmr.monthly_rate) }}{% endfor %}"); print(t.render(kamar_tersedia=data));